description:
Implement the three JS modules that wire the map to the server-rendered shell. All JS lives under static/js/events/ (this directory does not exist yet — create it). Target: combined LOC < 300 (T1 tripwire).

Design doc: docs/plans/2026-04-20-phase-0.4-htmx-map-spike-design.md (sections 'Architecture', 'File layout', 'Acceptance criteria', 'Back/forward nav QA checklist')
ADR-004 D1/D4: hx-preserve, single Alpine.store, custom DOM events, no setTimeout, no manual DOM hand-syncing.

Depends on: kb-hg3.2 must be complete — templates/events/list.html must load these scripts, and /events/<event_id>/drawer/ endpoint must exist.

## Codebase context (read before implementing)

- static/ directory exists at /workspace/static/ but static/js/ does not exist. Create static/js/events/.
- _base.html already loads Alpine.js (CDN: alpinejs@3.x.x) and HTMX. Do NOT add them again.
- list.html (created in kb-hg3.2) loads these three files via {% static %} at the bottom. The load order is: store.js, then map.js, then bridge.js. All three are plain <script> tags (not ES modules), so they share the global window scope — initMap must be assigned to window.
- The drawer URL pattern is /events/<event_id>/drawer/ (name='event-drawer'). Since these are static JS files (not Django templates), the URL is constructed by string interpolation, not {% url %}.
- MapLibre GL JS and its CSS are loaded by list.html via unpkg CDN before the static JS files. window.maplibregl is available when these scripts run.
- Alpine.store('map', ...) must be registered before Alpine initializes (inside 'alpine:init' listener). bridge.js runs after Alpine is initialized (inside 'alpine:initialized' listener).

## Files to create

All three files are plain scripts (no import/export). They communicate via window globals (window.initMap) and window events.

### 1. CREATE static/js/events/store.js

Registers the Alpine store. Must fire inside 'alpine:init' so it is available before Alpine processes the DOM.

    document.addEventListener('alpine:init', function () {
      Alpine.store('map', {
        selectedEventId: null,
        hoveredEventId: null,
        bounds: null,
        _mapInstance: null,

        selectEvent: function (eventId) {
          this.selectedEventId = eventId
          var url = new URL(window.location)
          if (eventId) {
            url.searchParams.set('selected', eventId)
          } else {
            url.searchParams.delete('selected')
          }
          history.pushState({}, '', url)
          window.dispatchEvent(new CustomEvent('events:selection-changed', { detail: { eventId: eventId } }))
        },

        hoverEvent: function (eventId) {
          this.hoveredEventId = eventId
        },

        setBounds: function (bounds) {
          this.bounds = bounds
          var url = new URL(window.location)
          if (bounds) {
            url.searchParams.set('bounds', [bounds.lat_min, bounds.lng_min, bounds.lat_max, bounds.lng_max].join(','))
          } else {
            url.searchParams.delete('bounds')
          }
          history.replaceState({}, '', url)
          window.dispatchEvent(new CustomEvent('events:bounds-changed', { detail: { bounds: bounds } }))
        },
      })
    })

Design note: selectEvent uses pushState (selection is semantic state — back closes drawer). setBounds uses replaceState (viewport state — back restores filters, not pan position). See design doc 'Back/forward nav' section.

### 2. CREATE static/js/events/map.js

Defines window.initMap. Plain function assigned to window so bridge.js can call it.

    window.initMap = function (containerEl, store) {
      // Read initial markers from DOM data island
      var markersDataEl = document.getElementById('markers-data')
      var markersGeoJSON = markersDataEl
        ? JSON.parse(markersDataEl.textContent)
        : { type: 'FeatureCollection', features: [] }

      // Read initial bounds from URL
      var params = new URLSearchParams(window.location.search)
      var boundsParam = params.get('bounds')
      var initialBounds = [13.28, 52.45, 13.48, 52.58]  // Berlin fallback
      if (boundsParam) {
        var parts = boundsParam.split(',').map(Number)
        if (parts.length === 4 && parts.every(function (n) { return !isNaN(n) })) {
          // bounds param is lat_min,lng_min,lat_max,lng_max
          initialBounds = [parts[1], parts[0], parts[3], parts[2]]  // [lng_min, lat_min, lng_max, lat_max]
        }
      }

      var map = new maplibregl.Map({
        container: containerEl,
        style: 'https://demotiles.maplibre.org/style.json',
        bounds: initialBounds,
        fitBoundsOptions: { padding: 20 },
      })

      map.on('load', function () {
        map.addSource('events', {
          type: 'geojson',
          data: markersGeoJSON,
          cluster: true,
          clusterMaxZoom: 14,
          clusterRadius: 50,
        })

        map.addLayer({
          id: 'event-clusters',
          type: 'circle',
          source: 'events',
          filter: ['has', 'point_count'],
          paint: {
            'circle-color': '#6366f1',
            'circle-radius': 18,
            'circle-opacity': 0.8,
          },
        })

        map.addLayer({
          id: 'event-markers',
          type: 'circle',
          source: 'events',
          filter: ['!', ['has', 'point_count']],
          paint: {
            'circle-color': '#a855f7',
            'circle-radius': 8,
            'circle-opacity': 0.9,
          },
        })
      })

      map.on('moveend', function () {
        var b = map.getBounds()
        store.setBounds({
          lat_min: b.getSouth(),
          lng_min: b.getWest(),
          lat_max: b.getNorth(),
          lng_max: b.getEast(),
        })
      })

      map.on('click', 'event-markers', function (e) {
        var feature = e.features[0]
        if (!feature) return
        var eventId = feature.properties.event_id
        store.selectEvent(eventId)
        htmx.ajax('GET', '/events/' + eventId + '/drawer/', {
          target: '#drawer',
          swap: 'innerHTML',
        })
      })

      window.addEventListener('events:selection-changed', function (e) {
        // Visual highlight — set feature state on the selected event marker
        // MapLibre feature state requires a numeric feature id; use a filter layer instead
        map.setPaintProperty('event-markers', 'circle-color', [
          'case',
          ['==', ['get', 'event_id'], e.detail.eventId || -1],
          '#f59e0b',
          '#a855f7',
        ])
      })

      window.addEventListener('events:filter-changed', function () {
        var el = document.getElementById('markers-data')
        if (!el) return
        var newGeoJSON = JSON.parse(el.textContent)
        map.getSource('events').setData(newGeoJSON)
      })

      return {
        destroy: function () { map.remove() },
      }
    }

Note on private venues: private venue features have geometry: null (set by the server). MapLibre skips null-geometry features automatically — they won't appear as pins. The 1000m obfuscation circle visualisation is deferred to Phase 0.4 proper (out of spike scope).

Note on drawer URL: the URL is hardcoded as '/events/' + eventId + '/drawer/'. This matches the URL pattern added in kb-hg3.2. If the app is not mounted at the root, adjust accordingly.

### 3. CREATE static/js/events/bridge.js

Single wiring point (T4 tripwire — glue in exactly one place). Connects Alpine store and map instance on page load.

    document.addEventListener('DOMContentLoaded', function () {
      var mapEl = document.getElementById('map')
      if (!mapEl) return  // guard: only run on pages with the map

      document.addEventListener('alpine:initialized', function () {
        var store = Alpine.store('map')
        var mapController = window.initMap(mapEl, store)
        store._mapInstance = mapController

        // Restore ?selected= from URL on initial load (e.g. after reload or forward nav)
        var params = new URLSearchParams(window.location.search)
        var selected = params.get('selected')
        if (selected) {
          htmx.ajax('GET', '/events/' + selected + '/drawer/', {
            target: '#drawer',
            swap: 'innerHTML',
          })
        }
      })

      // After HTMX swaps #event-list, tell map.js to re-read marker data from DOM
      document.body.addEventListener('htmx:afterSwap', function (evt) {
        if (evt.detail.target.id === 'event-list') {
          window.dispatchEvent(new CustomEvent('events:filter-changed', {}))
        }
      })
    })

## Verification

1. python manage.py runserver, load /events — map canvas renders (not a blank grey box), Berlin markers visible.
2. Open browser devtools Console tab — no console.error on load.
3. Submit the filter form — HTMX swap fires, map markers update (count changes).
4. Click a visible marker — #drawer fills with event title and details.
5. Click a list card — no JS error (store.selectEvent called via onclick in _event_list.html).
6. Open a new tab at /events?selected=<valid_event_id> — drawer opens automatically.
7. T1 check: wc -l static/js/events/store.js static/js/events/map.js static/js/events/bridge.js — total should be < 300 lines.
8. T5 check: grep -rn 'setTimeout' static/js/events/ — should return no matches.

