  </header>

  {% if organizer.description %}
  <section class="prose prose-sm max-w-none">
    {{ organizer.description|linebreaks }}
  </section>
  {% endif %}

  <section>
    <h2 class="text-xl font-semibold mb-4">{% trans "Upcoming events" %}</h2>
    {% if upcoming_events %}
    <div class="flex flex-col gap-3">
      {% for event in upcoming_events %}
        <c-event-card :event="event" />
